command(python -c "import os, shutil, filecmp
hermes_base = r'E:\HERMES\skills'
gemini_base = r'C:\Users\yudah\.gemini\config\skills'

updated = []
added = []

for root, dirs, files in os.walk(hermes_base):
    if 'SKILL.md' in files:
        skill_name = os.path.basename(root)
        dest_dir = os.path.join(gemini_base, skill_name)
        if not os.path.exists(dest_dir):
            added.append((root, dest_dir))
        else:
            # check if any file in root is newer or different
            for f in files:
                src_f = os.path.join(root, f)
                dst_f = os.path.join(dest_dir, f)
                if not os.path.exists(dst_f):
                    updated.append((src_f, dst_f))
                elif os.path.getmtime(src_f) > os.path.getmtime(dst_f) and not filecmp.cmp(src_f, dst_f, shallow=False):
                    updated.append((src_f, dst_f))

print(f'Skills to add: {len(added)}')
for src, dst in added:
    print(' +', os.path.basename(src))
print(f'Files to update: {len(updated)}')
for src, dst in updated:
    print(' ~', os.path.basename(os.path.dirname(src)), os.path.basename(src))
")

